    [DataRow("19.99", "$", "$19.99")]
    [DataRow("0.50", "£", "£0.50")]
    [DataRow("1234.10", "$", "$1234.10")]
    public void FormatCurrency_VariousAmounts_ReturnsExpectedFormat(string amount, string symbol, string expected)
    {
        var result = _formatter.FormatCurrency(decimal.Parse(amount), symbol);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void FormatCurrency_NegativeAmount_ContainsMinusSign()
    {
        var result = _formatter.FormatCurrency(-5.99m);

        Assert.Contains("-", result);
    }
}

